def grev(g, a, b):
    ids = set(H.orders_in(dh, a, b)['Mã chứng từ'])
    s = ct[ct['Mã đơn hàng'].isin(ids) & (ct['group_n'] == H.norm(g))]
    return float(s['rev'].sum())


def unit_qty(unit, a, b):
    ids = set(H.orders_in(dh, a, b)['Mã chứng từ'])
    s = ct[ct['Mã đơn hàng'].isin(ids) & (ct['base_unit'] == unit)]
    return float(s['qty'].sum())
